def move_heroes(apps, schema_editor):
    Person = apps.get_model("core", "Person")
    Hero = apps.get_model("core", "Hero")
    Bookmark = apps.get_model("core", "Bookmark")
    for i, p in enumerate(Person.objects.filter(person_type="qahramon").order_by("order", "full_name")):
        h = Hero.objects.create(
            full_name=p.full_name, slug=p.slug, rank="", birth_date=p.birth_date, bio=p.bio,
            awards=p.awards, photo=p.photo.name if p.photo else "", source_url=getattr(p, "source_url", ""),
            department_id=p.department_id, views=p.views, order=i + 1,
        )
        Bookmark.objects.filter(content_type="shaxs", object_id=p.pk).update(content_type="qahramon", object_id=h.pk)
        p.delete()


def back(apps, schema_editor):
    Person = apps.get_model("core", "Person")
    Hero = apps.get_model("core", "Hero")
    for h in Hero.objects.all():
        Person.objects.create(full_name=h.full_name, slug=h.slug, person_type="qahramon", birth_date=h.birth_date,
                              bio=h.bio, awards=h.awards, photo=h.photo.name if h.photo else "", order=40 + h.order)
        h.delete()



